iterations.reply:
Two files follow. Per the platform team's approved grant extension, I added the `aap:caps/http-client@0.1.0` import and the enrichment fetch. The `PublishedDigest` input has no `text` field, so I used its `date` as the query value, percent-encoded. The result of the fetch is discarded and a transport failure is ignored, so the output is unchanged.

The node records ids as seen only when `published` is true, which is my reading of the node's intent. `recorded` counts ids newly written and is never negative.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{published-digest, run-report};

    import aap:caps/state-rw@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(published: published-digest) -> run-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Approved enrichment fetch; result is intentionally ignored so the
        // node's output is unchanged (transport failures are values, not traps).
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&published.date)
        );
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            for id in &published.considered {
                if state_rw::get(id).is_none() {
                    state_rw::put(id, "seen");
                    recorded += 1;
                }
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

